import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz a dummy uint256 to satisfy the requirement that the fuzzer supplies inputs
    function testFuzz_property(uint256 dummy) public {
        // keep dummy unconstrained; it is irrelevant to behavior but required as a fuzz param

        // call version and capture its return value
        string memory v = c.version();

        // The universal property: the reference ALWAYS returns "1.0.0" for any input; assert that here.
        // The mutant that changed the string to "2.0.0" will cause this assertion to fail for some fuzz input(s).
