pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure we don't hard-code any deciding value
    function testFuzz_property(address caller) public {
        // keep caller wide but non-zero to avoid degenerate zero-address behavior
        vm.assume(caller != address(0));

        // Call version() from an arbitrary caller; version is external pure so msg.sender irrelevant
        bool ok;
        try c.version() returns (string memory v) {
            // property: returned string is non-empty
            ok = bytes(v).length != 0;
        } catch {
            // should not revert for either reference or mutant; treat revert as failure
            ok = false;
        }

        // The reference contract returns "1.0.0" for all inputs, so this assertTrue holds for all inputs.
        // The mutant that returns "" will make this assertion fail for some input (and indeed for all inputs),
        // causing the test to fail on the buggy version.
        assertTrue(ok);
    }
}

