pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing any arbitrary uint256 to satisfy the requirement of at least one fuzzed parameter
    function testFuzz_property(uint256 arbitrary) public {
        // keep the fuzzed parameter but it does not influence version(); ensures fuzzer explores inputs
        // Call version and capture return via try/catch to be robust if mutant were to revert (it does not)
        bool ok;
        try c.version() returns (string memory s) {
            // The reference returns "1.0.0" (no leading 'v'). We assert that the returned string does NOT start with 'v'.
            // Check: if the string has length >=1 and first byte is 'v' then it's mutated. We assert the negation.
            bytes memory b = bytes(s);
            if (b.length == 0) {
                // empty string would violate semantic expectation; mark as false
                ok = false;
            } else {
                ok = (b[0] != bytes1(uint8(0x76))); // 0x76 == 'v'
            }
        } catch {
            ok = false;
        }

        // Reference contract always satisfies: version() does not start with 'v'. Mutant with "v1.0.0" will fail for many fuzz inputs.
        assertTrue(ok);
    }
}

