pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to ensure we don't hard-code an actor; version() is external pure so caller doesn't matter
    function testFuzz_property(address caller) public {
        // keep wide domain but avoid zero address just as a courtesy (not required)
        if (caller == address(0)) caller = address(1);

        // call version() from fuzzed caller to exercise external call context
        string memory v;
        vm.prank(caller);
        v = c.version();

        // The reference contract always returns "1.0.0" for any call; the mutant that changed the returned string will fail this assertion for some caller values
        assertTrue(keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
}

